import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"月球工业伴星与空间太阳能电站：一个 1979 年构想的 2026 年版","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/space-energy/lunar-industrial-satellite.md","filePath":"topics/space-energy/lunar-industrial-satellite.md"}'),g={name:"topics/space-energy/lunar-industrial-satellite.md"};function d(e,t,a,l,i,u){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="月球工业伴星与空间太阳能电站-一个-1979-年构想的-2026-年版" tabindex="-1">月球工业伴星与空间太阳能电站：一个 1979 年构想的 2026 年版 <a class="header-anchor" href="#月球工业伴星与空间太阳能电站-一个-1979-年构想的-2026-年版" aria-label="Permalink to &quot;月球工业伴星与空间太阳能电站：一个 1979 年构想的 2026 年版&quot;">​</a></h1><blockquote><p>关键词：空间太阳能电站、太空太阳能、微波无线传能、月球工业化、工业伴星、ISRU 就地取材、逐日工程、欧米伽 OMEGA、段宝岩、Glaser 格拉泽、NASA CR-2357、Lunar Resources Utilization、O&#39;Neill 奥尼尔、The High Frontier、Caltech、MAPLE、SSPD-1、JAXA、三菱重工、ESA SOLARIS、重庆璧山、氦-3、整流天线 rectenna、地球同步轨道 GEO、时间错位、构想不等于进展</p></blockquote><p><strong>核实对象</strong>：2026-10-24 用户转来王钦文 × 马兆远访谈摘要的收尾构想段</p><blockquote><p>「将月球打造为地球的工业伴星。通过在月球铺设巨大面积的太阳能发电站并将能量传回地球，有望彻底解决人类的能源需求，让地球重回生态平衡的时代。」</p></blockquote><p><strong>核实结论一句话</strong>：<strong>构想方向有真实学术源流且已被量化论证过 —— 但不是在 2026 年，而是在 1979 年。</strong> 把 47 年前的 NASA 方案讲成&quot;最后提出的宏大构想&quot;，是本篇最值得记录的一处失真（时间错位）。技术上它没有错，但它被&quot;新&quot;这个字包装了。</p><hr><h2 id="一、逐条核实" tabindex="-1">一、逐条核实 <a class="header-anchor" href="#一、逐条核实" aria-label="Permalink to &quot;一、逐条核实&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>转述的说法</th><th>判定</th><th>依据</th></tr></thead><tbody><tr><td>1</td><td>月球铺太阳能电站、能量传回地球</td><td>✅ <strong>构想属实、有源流</strong></td><td>见 §二 1979 NASA 报告</td></tr><tr><td>2</td><td>这是&quot;视频最后提出的宏大构想&quot;</td><td>⚠️ <strong>时间错位</strong></td><td>1979-04-30 NASA 报告已量化论证；O&#39;Neill 1976 已提出</td></tr><tr><td>3</td><td>&quot;彻底解决人类的能源需求&quot;</td><td>⚠️ <strong>程度夸大</strong></td><td>当前实测：Caltech 地面只收到 <strong>&lt;0.1 µW</strong>；逐日工程百米级 DC-DC <strong>20.8%</strong></td></tr><tr><td>4</td><td>地点：<strong>月球</strong></td><td>⚠️ <strong>路线错位</strong></td><td>全球主流（含中国逐日工程）走 <strong>GEO 地球同步轨道</strong>，不是月球表面</td></tr><tr><td>5</td><td>&quot;重回生态平衡的时代&quot;</td><td>⚠️ 修辞</td><td>无可检验内容</td></tr><tr><td>6</td><td>马兆远本人是否书面提出该构想</td><td>❓ <strong>未找到书面出处</strong></td><td>检索无果；本项不作肯定判断</td></tr></tbody></table><blockquote><p>⚠️ 说明：我拿到的是<strong>文字摘要</strong>，不是视频本身。因此&quot;他是否真的这么说&quot;&quot;他引用罗素的具体篇目&quot;这类<strong>言说归属</strong>问题我无法独立核实，只能核实<strong>观点本身的真伪与源流</strong>。这是合法状态。</p></blockquote><hr><h2 id="二、★-关键发现-「月球当工业基地」不是新构想-是-1979-年的-nasa-结论" tabindex="-1">二、★ 关键发现：「月球当工业基地」不是新构想，是 1979 年的 NASA 结论 <a class="header-anchor" href="#二、★-关键发现-「月球当工业基地」不是新构想-是-1979-年的-nasa-结论" aria-label="Permalink to &quot;二、★ 关键发现：「月球当工业基地」不是新构想，是 1979 年的 NASA 结论&quot;">​</a></h2><p>这条构想有一个非常精确的出处，而且结论比今天的说法更硬：</p><blockquote><p><strong>1979 年 4 月 30 日</strong>，General Dynamics 公司 Convair 分部向 NASA 提交最终报告 《<strong>Lunar Resources Utilization for Space Construction</strong>》（月球资源利用于空间建造）， NASA 合同号 <strong>NAS9-15560</strong>，报告编号 GDC-ASP79-001，NTRS 编号 19830077470。 报告结论：<strong>对&quot;30 座、每座 10 GW&quot;规模的太阳能发电卫星系统而言，使用月球资源比使用地球材料更便宜。</strong></p></blockquote><p>也就是说：<strong>46 年前就已经不是&quot;能不能想&quot;的问题，而是&quot;算过账了&quot;的问题</strong> —— 月球材料之所以便宜，是因为月球重力低、没有大气阻力，从月面发射成本远低于从地球发射。</p><p><strong>更早的源头</strong>：普林斯顿的 <strong>Gerard K. O&#39;Neill（奥尼尔）</strong> 在 1970 年代就指出高发射成本问题，提出<strong>用月球材料在轨道上建造太阳能发电卫星</strong>（《The High Frontier: Human Colonies in Space》，1976）。</p><p><strong>背景代价</strong>：这个 1970 年代方案依赖当时 NASA 对航天飞机发射成本的<strong>过分乐观的估算</strong>。1980 年航天飞机实际成本暴露后，O&#39;Neill 等人不得不另寻路线。★ 这一条值得单独记住：<strong>&quot;月球更便宜&quot;的结论是建立在一个后来破产的发射成本假设之上的</strong> —— 2026 年重提这个构想，第一件事应该是重算这笔账，而不是当成新展望。</p><hr><h2 id="三、空间太阳能电站-sbsp-六十年-who-when-硬数据" tabindex="-1">三、空间太阳能电站（SBSP）六十年：who / when / 硬数据 <a class="header-anchor" href="#三、空间太阳能电站-sbsp-六十年-who-when-硬数据" aria-label="Permalink to &quot;三、空间太阳能电站（SBSP）六十年：who / when / 硬数据&quot;">​</a></h2><p>整条时间线里，<strong>每一次&quot;突破&quot;都同时带一个量化上限</strong> —— 这是这类新闻最容易被省略的部分。</p><h3 id="_3-1-发明与立项-1968–1979" tabindex="-1">3.1 发明与立项（1968–1979） <a class="header-anchor" href="#_3-1-发明与立项-1968–1979" aria-label="Permalink to &quot;3.1 发明与立项（1968–1979）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>事件</th><th>硬数据</th></tr></thead><tbody><tr><td><strong>1968-11</strong></td><td>Peter Glaser（格拉泽）在 <em>Science</em> 发表 <strong>&quot;Power from the Sun: Its Future&quot;</strong>（162(3856):857–61, PMID 17769070）</td><td>SBSP 概念首次提出，原名 Satellite Solar Power System (SSPS)</td></tr><tr><td><strong>1973-12-25</strong></td><td>Glaser 获美国专利 <strong>3,781,647</strong>《Method And Apparatus For Converting Solar Radiation To Electrical Power》</td><td>用微波从太空天线（<strong>大至 1 平方公里</strong>）向地面更大的整流天线（rectenna）传能</td></tr><tr><td><strong>1974-02</strong></td><td>NASA 委托 Arthur D. Little 牵头四家公司联合研究（<strong>NASA CR-2357</strong>）</td><td>结论：存在多个重大难题 —— <strong>主要是把材料送入轨道的费用</strong>、以及缺乏如此大型太空工程的经验</td></tr><tr><td><strong>1975-09</strong></td><td>JPL / Raytheon 试验</td><td>传输 <strong>30 kW</strong>，距离 <strong>1 英里</strong>，效率 <strong>9.6%</strong></td></tr><tr><td><strong>1979</strong></td><td>★ 上述月球资源利用报告</td><td><strong>30 座 × 10 GW</strong>，月球材料更便宜</td></tr></tbody></table><h3 id="_3-2-沉寂与重启-1990s–2015" tabindex="-1">3.2 沉寂与重启（1990s–2015） <a class="header-anchor" href="#_3-2-沉寂与重启-1990s–2015" aria-label="Permalink to &quot;3.2 沉寂与重启（1990s–2015）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>事件</th><th>硬数据</th></tr></thead><tbody><tr><td><strong>1991–1993</strong></td><td>美国 <strong>SELENE</strong>（SpacE Laser ENErgy）项目：研究激光传能为月球基地供电</td><td>两年研究，因<strong>转运营成本过高</strong>于 1993 年结束，<strong>未到达天基演示</strong></td></tr><tr><td><strong>2008</strong></td><td>日本通过《宇宙基本法》，将空间太阳能列为<strong>国家目标</strong></td><td>—</td></tr><tr><td><strong>2015-03-12</strong></td><td><strong>JAXA</strong> 宣布无线传能试验成功</td><td><strong>1.8 kW，传输 50 米</strong></td></tr><tr><td><strong>2015 年初</strong></td><td><strong>三菱重工</strong>演示</td><td><strong>10 kW，传 500 米</strong>（微波）</td></tr><tr><td><strong>2015</strong></td><td>**中国空间技术研究院（CAST）**在国际空间发展大会上展示路线图</td><td>—</td></tr></tbody></table><h3 id="_3-3-近期与现状-2019–2026" tabindex="-1">3.3 近期与现状（2019–2026） <a class="header-anchor" href="#_3-3-近期与现状-2019–2026" aria-label="Permalink to &quot;3.3 近期与现状（2019–2026）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>事件</th><th>硬数据</th></tr></thead><tbody><tr><td><strong>2019-02</strong></td><td>《科技日报》报道中国<strong>重庆璧山</strong>试验基地<strong>开工</strong>；CAST 副院长<strong>李明</strong>称中国期望成为<strong>首个建成有实用价值空间太阳能电站</strong>的国家</td><td>计划 <strong>2021–2025</strong> 发射若干中小型空间电站</td></tr><tr><td><strong>2020-11-14</strong></td><td>英国政府委托空间太阳能电站研究</td><td>—</td></tr><tr><td><strong>2021-08</strong></td><td><strong>Caltech</strong> 宣布 2023 年前发射 SBSP 试验阵列；披露 <strong>Donald Bren 夫妇自 2013 年起资助其空间太阳能项目，捐款超 1 亿美元</strong></td><td>—</td></tr><tr><td><strong>2022</strong></td><td>英国 <strong>Space Energy Initiative</strong> 宣布 <strong>2040 年代中期</strong>发射首座空间电站</td><td>号称&quot;提供英国 30% 电力需求&quot;</td></tr><tr><td><strong>2022</strong></td><td><strong>ESA</strong> 提出 <strong>SOLARIS</strong> 计划</td><td>目标 <strong>2030 年</strong>起运行太阳能发电卫星</td></tr><tr><td><strong>2023-03-03</strong></td><td>★ <strong>Caltech SSPD-1</strong> 上的 <strong>MAPLE</strong> 实验（Ali Hajimiri 团队）<strong>首次在太空演示无线传能</strong>：选择性把功率定向给太空中两个不同接收器，并向地球传去&quot;可探测功率&quot;</td><td><strong>EIRP 仅 3.2 W（+35 dBm）</strong>，&quot;远低于商业通信卫星常见的千瓦级&quot;；<strong>地面探测到的功率约 −45 dBm，即不到 0.1 微瓦</strong></td></tr><tr><td><strong>2024</strong></td><td>MAPLE 结果发表于 <em>Acta Astronautica</em>（Mizrahi 等，arXiv:2401.15267）</td><td>同上</td></tr><tr><td><strong>2026-03-02</strong></td><td>《人民日报》刊登段宝岩院士署名文章《多国加快推进空间太阳能电站技术研发——把太阳能电站&quot;搬上天&quot;》</td><td>附图含&quot;逐日工程——欧米伽空间太阳能电站&quot;</td></tr><tr><td><strong>2026-05-18</strong></td><td>★ <strong>新华社</strong>：段宝岩团队&quot;逐日工程&quot;取得重大进展</td><td>见 §四</td></tr><tr><td><strong>2026-07-12</strong></td><td>有报道称中国科学家提出<strong>月球南极附近的激光供能塔</strong>，用于跨月面无线传能</td><td>⚠️ 单一外媒来源，未在本次核实中二次确认</td></tr></tbody></table><h3 id="_3-4-★-规模问题的硬账-这条最能说明难度" tabindex="-1">3.4 ★ 规模问题的硬账（这条最能说明难度） <a class="header-anchor" href="#_3-4-★-规模问题的硬账-这条最能说明难度" aria-label="Permalink to &quot;3.4 ★ 规模问题的硬账（这条最能说明难度）&quot;">​</a></h3><ul><li>按太阳能板 <strong>20 kg/kW</strong> 估算（不计支撑结构、天线、聚光镜减重），<strong>一座 4 GW 空间电站重约 80,000 公吨</strong>，全部要从地球发射。</li><li>2015 年实际飞行器水平是 <strong>150 W/kg（即 6.7 kg/kW）</strong>；轻量化设计乐观估计可达 <strong>1 kg/kW</strong>。</li><li>GEO 传能时，发射天线波束扩散到地面约 <strong>10 公里直径</strong>（艾里斑第一零点环），<strong>整体传输效率接近 50%</strong>。</li></ul><p>→ 结论：<strong>&quot;效率&quot;和&quot;减重&quot;是两个必须同时解决的问题，而且它们是乘积关系</strong>。任何单点突破都不足以让系统成立。</p><hr><h2 id="四、★★-中国的真实现状-逐日工程走的是-geo-不是月球" tabindex="-1">四、★★ 中国的真实现状：逐日工程走的是 GEO，不是月球 <a class="header-anchor" href="#四、★★-中国的真实现状-逐日工程走的是-geo-不是月球" aria-label="Permalink to &quot;四、★★ 中国的真实现状：逐日工程走的是 GEO，不是月球&quot;">​</a></h2><p>这是本篇最值得澄清的&quot;路线错位&quot;。中国确实在认真做空间太阳能电站，但<strong>它的方案是地球同步轨道的分布式欧米伽（OMEGA）电站，不是月球电站</strong>。</p><p><strong>&quot;逐日工程&quot;（空间太阳能电站系统项目）事实清单</strong>（新华社 2026-05-18 + 西安电子科技大学官网 + 百度百科）：</p><ul><li>全称：<strong>空间太阳能电站系统项目</strong>，由<strong>西安电子科技大学段宝岩院士团队牵头</strong></li><li>论证基础：<strong>2014 年</strong>国家工信部、发改委、科技部等 <strong>16 个部委</strong>组织的专家组论证</li><li>依托：<strong>陕西省空间太阳能电站系统重点实验室</strong></li><li>启动：<strong>2018-12-23 在西安启动</strong></li><li><strong>2014 年</strong>段宝岩团队提出<strong>欧米伽（OMEGA）创新设计方案</strong>（2026 年进一步提出&quot;分布式欧米伽&quot;方案）</li><li><strong>2022-06-05</strong>：世界首个<strong>全链路全系统</strong>空间太阳能电站<strong>地面验证系统</strong>通过专家组验收</li><li><strong>2026-05-18 新华社</strong>公布的最新测试数据 ★： <ul><li><strong>百米级距离：直流—直流传输效率 20.8%，输出功率 1180 瓦，波束收集效率 88.0%</strong></li><li><strong>无人机微波无线传能系统</strong>：时速 30 公里、距离 30 米条件下，实现 <strong>143 瓦</strong>稳定接收</li><li>攻克&quot;一对多动目标微波无线传能&quot;——一套发射系统为多个移动目标供电</li><li>陕西省技术转移中心成果评价会专家组意见：成果&quot;总体达到国际领先水平&quot;</li></ul></li><li>段宝岩的定位表述（新华社原文）：空间太阳能电站好比<strong>部署在太空预定轨道的&quot;空间微波充电桩&quot;</strong>，可打破传统卫星对自身太阳能帆板的单一依赖</li></ul><p>★ 注意这里的<strong>口径</strong>：<strong>&quot;地面验证系统&quot;通过验收 ≠ 电站上天</strong>。20.8% 是<strong>百米级地面试验</strong>的 DC-DC 效率。这一步很扎实，但它离&quot;在天上发电、把电传回地面&quot;还有从地面到轨道的距离。</p><h3 id="月球路线-vs-geo-路线-为什么主流不选月球" tabindex="-1">月球路线 vs GEO 路线：为什么主流不选月球 <a class="header-anchor" href="#月球路线-vs-geo-路线-为什么主流不选月球" aria-label="Permalink to &quot;月球路线 vs GEO 路线：为什么主流不选月球&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>GEO（主流路线）</th><th>月球表面（马教授方案）</th></tr></thead><tbody><tr><td>距地距离</td><td>约 3.6 万 km</td><td>约 38 万 km（<strong>~10 倍</strong>）</td></tr><tr><td>昼夜</td><td>几乎恒照（除春秋分食季）</td><td><strong>14 天连续黑夜</strong>，储能/核电需求刚性</td></tr><tr><td>发射成本</td><td>材料全部从地球发射（80,000 t 级难题）</td><td>可就地取材（ISRU），但需先在月面建工业体系</td></tr><tr><td>关键风险</td><td>在轨组装、减重</td><td><strong>月尘</strong>、极端温差、超远距离传能、无先例</td></tr><tr><td>现实进度</td><td>有地面验证系统（中国、日本、美国多线）</td><td><strong>仅存于报告与构想</strong>（最新动向：2026-07 月球激光塔提案，尚待确认）</td></tr></tbody></table><p>→ 所以准确的表述是：<strong>&quot;月球工业伴星&quot;是一个有历史论证的方向，但它不是当前的工程路线。当前工程路线是 GEO。</strong> 把两者混起来讲，会让&quot;最新进展&quot;看起来比实际更接近月球方案。</p><hr><h2 id="五、回答访谈结尾的提问-技术瓶颈与最新进展" tabindex="-1">五、回答访谈结尾的提问：技术瓶颈与最新进展 <a class="header-anchor" href="#五、回答访谈结尾的提问-技术瓶颈与最新进展" aria-label="Permalink to &quot;五、回答访谈结尾的提问：技术瓶颈与最新进展&quot;">​</a></h2><p><strong>瓶颈（按&quot;乘积链&quot;排序，因为效率是乘出来的）</strong>：</p><ol><li><strong>发射成本与减重</strong> —— 最大瓶颈。4 GW 需 80,000 t；必须把 kg/kW 从 20 压到 1 量级</li><li><strong>在轨组装</strong> —— 平方公里级天线无先例</li><li><strong>无线传能效率</strong> —— 逐日工程地面百米级 <strong>20.8%</strong>（DC-DC）；GEO 整体传能理论近 <strong>50%</strong>，需整流天线 10 km 级</li><li><strong>&quot;最后一米&quot;功率密度</strong> —— Caltech 已是<strong>首次成功</strong>，但地面只收到 <strong>&lt;0.1 µW</strong>，对比商业通信卫星的千瓦级。这是&quot;原理通了、功率差好几个数量级&quot;的典型状态</li><li><strong>安全与频谱/监管</strong> —— 太空微波束涉及轨道安全、频率分配（此点本次未展开核实）</li></ol><p><strong>最新进展（按可信度排序）</strong>：</p><ul><li>✅ <strong>最实的</strong>：中国逐日工程 —— 2022-06 全链路地面验证系统验收；<strong>2026-05 百米级 1180 W / DC-DC 20.8% / 波束收集 88.0%</strong></li><li>✅ <strong>最有象征意义的</strong>：Caltech MAPLE（2023-03-03）—— <strong>人类第一次在太空完成无线传能演示</strong>，但功率只有 3.2 W EIRP</li><li>⏳ <strong>在计划中的</strong>：ESA SOLARIS（2030 起）、英国 Space Energy Initiative（2040 年代中期，号称覆盖英国 30% 电力）、中国 2021–2025 中小型电站计划</li><li>⚠️ <strong>要警惕的</strong>：2026-07 月球激光供能塔报道（单一外媒来源）；以及<strong>任何把&quot;构想/方案&quot;讲成&quot;进展/突破&quot;的表述</strong></li></ul><p><strong>时间表判断</strong>：<strong>&quot;彻底解决人类能源需求&quot;在可预见的未来不会发生。</strong> 现实的说法是：<strong>如果</strong>发射成本持续下降、<strong>且</strong>在轨组装与传能效率同时突破，<strong>才有机会在 2040 年代看到第一个有工程意义的千瓦级天基电站</strong>（英国和 ESA 的目标也就在这个量级和时间窗）。</p><hr><h2 id="六、跨主题连接" tabindex="-1">六、跨主题连接 <a class="header-anchor" href="#六、跨主题连接" aria-label="Permalink to &quot;六、跨主题连接&quot;">​</a></h2><ul><li>★★ <strong>罗素《闲散颂》1932</strong> —— 与技术乐观论同构的另一面：技术<strong>能不能</strong>改变人类处境，取决于<strong>怎么分配</strong>，而不是技术本身（见 <code>../philosophy/russell-in-praise-of-idleness.md</code>）</li><li>★ <strong>能量效率链的乘积结构 ↔ EnergySim</strong> —— 逐日工程的&quot;聚光效率 × 光电转换 × 微波转换 × 波束收集 × 整流 × DC-DC&quot;全链条相乘，与 <code>../energysim/</code> 里 PyPSA 的 <strong>Converter 效率</strong>建模是同一个问题：<strong>单环节 90% 听上去很好，六个环节相乘只剩 53%</strong></li><li>★ <strong>&quot;构想 ≠ 进展&quot;的判据 ↔ 证据硬度阶梯</strong> —— 把 1979 年方案说成&quot;最新构想&quot;，与 <code>../real-estate/</code> 里&quot;规划 ≠ 开工 ≠ 交付&quot;是同一类<strong>硬度跃迁</strong>错误：<strong>方案论证（低硬度）被表述成技术进展（高硬度）</strong></li><li><strong>极端环境可靠性 ↔ 风电</strong> —— 月面 14 天黑夜、月尘、极端温差，与 <code>../wind-energy/</code> 的&quot;现场可靠性优先于纸面效率&quot;同题</li><li><strong>1970 年代&quot;太空殖民&quot;乐观主义的破产</strong> —— 1979 报告依赖航天飞机成本假设，1980 年该假设破灭 → 与 <code>../economic-cycles/</code>、&quot;技术乐观主义周期&quot;呼应</li></ul><hr><h2 id="七、核实方法与来源" tabindex="-1">七、核实方法与来源 <a class="header-anchor" href="#七、核实方法与来源" aria-label="Permalink to &quot;七、核实方法与来源&quot;">​</a></h2><ul><li>一手/权威：新华社 2026-05-18（逐日工程数据）、西安电子科技大学新闻网（2022-06-05 验收）、<em>Science</em> 1968 Glaser 论文、USPTO 3,781,647、NASA CR-2357、NASA NTRS 19830077470（1979 月球资源报告）、Caltech 官网 2023-06-01 新闻、<em>Acta Astronautica</em> 2024（arXiv:2401.15267）</li><li>百科类：Wikipedia <code>Space-based solar power</code>（en）/<code>太空太陽能</code>（zh）、百度百科&quot;逐日工程&quot;</li><li>⚠️ 本项<strong>未核实</strong>：访谈视频原文（仅有文字摘要）、&quot;俄罗斯工程院外籍院士&quot;头衔的机构性质、2026-07 月球激光塔报道的独立性</li><li>⚠️ 一处校方自相矛盾：南方科技大学<strong>中文师资页</strong>记马兆远 2005 年牛津博士，<strong>英文师资页</strong>记 2004 年（D.Phil.）—— 差 1 年，不影响身份判定，但记录在此</li></ul>',50)])])}const c=o(g,[["render",d]]);export{q as __pageData,c as default};
